/*
 * A011665  A binary m-sequence: expansion of the reciprocal of
 *          x^5+x^4+x^3+x^2+1.
 * https://oeis.org/A011665
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

/* Periodic binary m‑sequence generated by the reciprocal of
   x^5+x^4+x^3+x^2+1.
   Recurrence: a(n) = a(n-2) ^ a(n-3) ^ a(n-4) ^ a(n-5)  (n >= 5),
   with initial values a(0)=0, a(1)=0, a(2)=0, a(3)=0, a(4)=1.
   The sequence has period 31, hence a(n) = a(n-31). */

seq_t a(idx_t n)
{
    static seq_t period[31] = {0};
    static unsigned init = 0;

    if (!init) {
        period[0] = 0;
        period[1] = 0;
        period[2] = 0;
        period[3] = 0;
        period[4] = 1;
        for (idx_t i = 5; i < 31; ++i) {
            period[i] = period[i-2] ^ period[i-3] ^ period[i-4] ^ period[i-5];
        }
        init = 1;
    }

    return period[(size_t)(n % 31)];
}
